Object.assign(FIX, {
padthai:{list:["1 lb spaghetti or rice noodles (or 4 packs ramen, no flavor packets)","4 eggs","1 cup cooked chopped chicken (or 1/2 block tofu, cubed)","1 tablespoon peanut butter","1/4 cup soy sauce","Juice of 1 lime","2 tablespoons sugar","2 cups shredded cabbage","3 green onions, sliced","2 tablespoons oil"],
 steps:["Boil the noodles until just tender and drain.","Whisk the soy sauce, lime juice, sugar and peanut butter with 2 tablespoons hot water.","Heat the oil in a large skillet over medium high. Cook the chicken 2 minutes, then push aside and scramble the eggs.","Add the noodles, cabbage and sauce and toss 3 minutes until coated.","Top with green onion."]},
basilchicken:{list:["1 lb ground turkey, beef or pork","1 bunch fresh basil, leaves picked","3 tablespoons soy sauce","1 jalapeño, finely chopped","1 teaspoon sugar","1 teaspoon garlic powder","4 eggs","2 tablespoons oil","1 1/2 cups rice, with 3 cups water"],
 steps:["Cook the rice: bring the rice and water to a boil, cover and simmer on low 18 minutes.","Brown the meat in 1 tablespoon oil with the jalapeño and garlic, about 8 minutes.","Stir in the soy sauce and sugar, then the basil until just wilted.","Fry the eggs in the rest of the oil until the edges are crispy.","Serve the meat over rice with an egg on top."]},
lasagna:{list:["1 box (16 oz) lasagna noodles (about 12 noodles)","1 jar (24 oz) pasta sauce","1 lb ground beef or Italian sausage","1 cup cottage cheese","1 egg","2 cups shredded cheese","1 teaspoon Italian seasoning","1/2 cup water"],
 steps:["Heat oven to 375°F. Boil the noodles 2 minutes less than the box says and drain.","Brown the meat, drain, then stir in the sauce and water.","Mix the cottage cheese, egg and Italian seasoning.","In a 9x13 dish spread a little sauce, then layer noodles, cottage cheese mix, meat sauce and shredded cheese. Repeat 3 times.","Cover with foil and bake 30 minutes. Uncover and bake 15 minutes more.","Rest 10 minutes before cutting."]},
minestrone:{list:["4 oz small pasta","1 can (15 oz) kidney beans, drained","1 can (14 oz) diced tomatoes","2 carrots, diced","1 zucchini, diced","1/2 small onion, diced","6 cups chicken or vegetable broth","2 cups spinach","1 teaspoon Italian seasoning","1 tablespoon oil"],
 steps:["Cook the onion and carrot in the oil 6 minutes.","Add the tomatoes, broth, beans and Italian seasoning. Simmer 15 minutes.","Add the pasta and zucchini and cook 10 minutes.","Stir in the spinach until wilted."]},
aglio:{list:["1 lb spaghetti","1/3 cup oil","1 1/2 teaspoons garlic powder (or 6 cloves fresh garlic, sliced)","1/4 teaspoon red pepper flakes or chili powder","1/3 cup parmesan","2 tablespoons chopped parsley","1 tablespoon salt for the pasta water"],
 steps:["Boil the pasta in salted water. Save 1 cup of the water, then drain.","Warm the oil with the garlic and chili over low heat 2 minutes. Do not let it brown.","Add the pasta and 1/2 cup pasta water and toss until glossy.","Toss in the parmesan and parsley."]},
boxstroganoff:{list:["1 box (5.5 oz) beef stroganoff dinner kit","1 lb ground beef (or ground turkey)","Milk and hot water as the box says","1/4 cup sour cream","1 1/2 cups frozen peas"],
 steps:["Brown the beef in a large skillet and drain.","Stir in the milk, hot water, pasta and sauce mix from the box.","Bring to a boil, then cover and simmer as the box says, usually 10 to 12 minutes.","Stir in the sour cream.","Cook the peas and serve on the side."]},
stroganoff:{list:["1 lb ground beef","9 oz egg noodles","8 oz mushrooms, sliced","1/2 small onion, diced","2 tablespoons flour","2 cups beef or chicken broth","1 cup sour cream","1/2 teaspoon salt","1/4 teaspoon pepper"],
 steps:["Boil the noodles and drain.","Brown the beef with the onion and mushrooms, about 10 minutes. Drain.","Sprinkle in the flour and stir 1 minute.","Stir in the broth, salt and pepper and simmer 5 minutes until thick.","Take off the heat, stir in the sour cream and serve over the noodles."]},
hamburgersteak:{list:["1 lb ground beef, shaped into 4 oval patties","1 large onion, sliced","2 tablespoons flour","2 cups beef broth","1/2 teaspoon salt","1/4 teaspoon pepper","1 1/3 cups instant mashed potato flakes, with water, milk and butter as the box says","1 can (14 oz) green beans"],
 steps:["Season the patties with salt and pepper and brown 4 minutes per side. Set aside.","Cook the onion in the drippings 6 minutes until soft.","Stir in the flour for 1 minute, then slowly whisk in the broth.","Return the patties, cover and simmer 10 minutes in the gravy.","Make the mashed potatoes and warm the green beans."]},
countrychicken:{list:["1 1/4 lb chicken breasts, pounded thin","1 egg","1 cup flour, plus 3 tablespoons for gravy","2 cups milk, plus 1/4 cup for the egg","1/4 cup oil","1 teaspoon salt","1/2 teaspoon pepper","1 1/3 cups instant mashed potato flakes, with water, milk and butter as the box says"],
 steps:["Beat the egg with 1/4 cup milk. Mix 1 cup flour with the salt and pepper.","Dip the chicken in flour, then egg, then flour again.","Fry in the oil over medium 4 to 5 minutes per side until golden and 165°F inside. Set aside.","Pour off all but 3 tablespoons oil. Whisk in 3 tablespoons flour for 1 minute, then slowly whisk in 2 cups milk. Simmer until thick and season with pepper.","Make the mashed potatoes and smother everything with gravy."]},
burgers:{list:["1 lb ground beef, made into 4 patties","4 hamburger buns","4 slices cheese","4 lettuce leaves (or sliced onion)","Ketchup and mustard","1/2 bag (32 oz) frozen fries","1/2 teaspoon salt","1/4 teaspoon pepper"],
 steps:["Bake the fries as the bag says.","Press a small dent in the middle of each patty and season both sides with salt and pepper.","Cook in a hot skillet over medium high 4 minutes per side.","Add cheese for the last minute.","Toast the buns and build the burgers."]},
scratchmac:{list:["1 lb elbow macaroni","3 cups milk","4 tablespoons butter","1/4 cup flour","2 cups shredded cheese","1 cup diced ham","1 1/2 cups frozen peas","1/2 teaspoon salt"],
 steps:["Boil the macaroni, adding the peas for the last 2 minutes. Drain.","Melt the butter in the pot over medium. Whisk in the flour for 1 minute.","Slowly whisk in the milk and simmer 3 to 4 minutes until thick.","Take off the heat and stir in the cheese and salt until smooth.","Stir in the pasta, peas and ham."]},
tomatobasil:{list:["2 cans (14 oz each) diced tomatoes (or 2 cans tomato sauce)","1 cup chicken broth","1/2 cup milk or cream","1/2 bunch fresh basil, chopped","1 teaspoon sugar","1/2 teaspoon garlic powder","8 slices bread","8 slices cheese","4 tablespoons butter"],
 steps:["Simmer the tomatoes, broth, garlic and sugar 15 minutes.","Blend or mash until smooth. Stir in the milk and basil and keep warm.","Butter one side of each bread slice and build sandwiches with cheese inside.","Cook over medium 3 minutes per side until golden and melted.","Serve the grilled cheese with the soup."]},
caesarwrap:{list:["2 cups chopped cooked chicken (or 1 can chicken)","1 head romaine lettuce, chopped","1/3 cup parmesan","8 flour tortillas","1/3 cup mayo","Juice of 1 lemon","1/2 teaspoon garlic powder","1 cup croutons (or crushed crackers)"],
 steps:["Whisk the mayo, lemon juice, garlic powder and half the parmesan for the dressing.","Toss the lettuce, chicken, croutons and the rest of the parmesan with the dressing.","Spoon onto the tortillas and roll up tight.","Cut in half to serve."]},
musubi:{list:["1 can (12 oz) luncheon meat, sliced into 8 slices","1 1/2 cups short grain rice, with 2 cups water","4 nori sheets, cut in half","3 tablespoons soy sauce","2 tablespoons sugar"],
 steps:["Simmer the rice in the water, covered, 18 minutes. Rest 10 minutes.","Fry the slices in a skillet over medium 2 minutes per side.","Add the soy sauce and sugar and turn the slices until glazed and sticky.","Press rice into the cleaned can or with wet hands into a block the size of a slice.","Top with a slice of meat and wrap a nori strip around the middle. Wet the end to seal."]},
onigiri:{list:["1 1/2 cups short grain rice, with 2 cups water","2 cans (5 oz each) tuna, drained","3 tablespoons mayo","1 teaspoon soy sauce","4 nori sheets, cut into strips","1/2 teaspoon salt for your hands"],
 steps:["Simmer the rice in the water, covered, 18 minutes. Rest until warm enough to handle.","Mix the tuna, mayo and soy sauce.","Wet your hands and rub them with a little salt.","Flatten a handful of rice, add a spoonful of tuna, and press the rice around it into a triangle.","Wrap a strip of nori around the bottom."]},
blackbeansoup:{list:["3 cans (15 oz each) black beans, with liquid","1/2 small onion, diced","2 cups chicken or vegetable broth","1/2 cup salsa","1 teaspoon cumin","1 tablespoon oil","1/2 cup sour cream"],
 steps:["Cook the onion in the oil 5 minutes.","Add the beans with their liquid, broth, salsa and cumin. Simmer 15 minutes.","Mash or blend about half the soup until creamy.","Top bowls with sour cream."]},
bcburritos:{list:["8 flour tortillas","2 cans (16 oz each) refried beans","1 cup shredded cheese","1/2 cup salsa"],
 steps:["Warm the beans in a pot or the microwave.","Warm the tortillas.","Spread 1/3 cup beans on each, add cheese and salsa, fold the sides in and roll up.","Toast seam side down in a dry skillet over medium 2 minutes per side."]},
tunamelt:{list:["3 cans (5 oz each) tuna, drained","1/3 cup mayo","8 slices bread","8 slices cheese","3 tablespoons butter"],
 steps:["Mix the tuna and mayo.","Spread on 4 slices of bread, top with cheese and close with the other slices.","Butter the outsides.","Toast in a skillet over medium 3 minutes per side until golden and melted."]},
chilaquiles:{list:["1/2 bag (13 oz) tortilla chips","1 can (10 oz) red enchilada sauce (or 1 1/2 cups salsa)","4 eggs","1/2 cup shredded cheese","2 tablespoons diced onion","1/4 cup sour cream","1 tablespoon oil"],
 steps:["Warm the sauce in a large skillet over medium.","Add the chips and toss 1 minute until coated but still a little crunchy.","Fry the eggs in the oil in another pan.","Top the chips with eggs, cheese, onion and sour cream."]},
tamagoyaki:{list:["6 eggs","1 tablespoon sugar","2 teaspoons soy sauce","1 tablespoon oil","1 1/2 cups rice, with 3 cups water"],
 steps:["Cook the rice: bring the rice and water to a boil, cover and simmer on low 18 minutes.","Whisk the eggs, sugar and soy sauce.","Oil a nonstick pan over medium low. Pour in a thin layer of egg.","When almost set, roll it to one side. Oil the pan, add another thin layer, lift the roll so egg flows under, then roll it back up.","Repeat until the egg is used. Slice and serve with rice."]},
congee:{list:["1/2 cup rice","8 cups chicken broth","1/2 teaspoon ground ginger","4 eggs (or 1 cup cooked chicken)","3 green onions, sliced","2 tablespoons soy sauce"],
 steps:["Simmer the rice, broth and ginger, partly covered, about 1 hour, stirring now and then, until thick and creamy.","Soft boil the eggs 7 minutes, cool and peel.","Ladle into bowls and top with a halved egg, green onion and a drizzle of soy sauce."]},
masalaomelet:{list:["6 eggs","1/4 small onion, finely diced","1 tomato, diced","1 jalapeño, finely diced","1/2 teaspoon curry powder","1/4 bunch cilantro, chopped","1/4 teaspoon salt","1 tablespoon oil","4 slices bread or flatbread"],
 steps:["Whisk the eggs with the curry powder and salt.","Stir in the onion, tomato, jalapeño and cilantro.","Heat the oil in a nonstick pan over medium. Pour in half the eggs and cook until set, about 3 minutes.","Fold and slide out. Repeat with the rest. Serve with toast."]},
yogurtbowl:{list:["2 cups yogurt","2 tablespoons honey","1 cup granola (or 1/2 cup oats)","1 cup berries or 2 sliced bananas"],
 steps:["Spoon 1/2 cup yogurt into each bowl.","Top with fruit and granola.","Drizzle with honey."]},
kolaches:{list:["3 1/4 cups flour","1 packet (2 1/4 teaspoons) yeast","1 cup warm milk","4 tablespoons butter, melted","1 egg","3 tablespoons sugar","1/2 teaspoon salt","8 hot dogs or smoked sausage links","1/2 cup shredded cheese"],
 steps:["Stir the yeast and sugar into the warm milk. Let sit 5 minutes until foamy.","Mix in the butter, egg, salt and flour and knead 5 minutes into a soft dough. Cover and rise 1 hour.","Divide into 8 pieces. Flatten each, add a sprinkle of cheese and a sausage, and pinch the dough closed around it.","Set seam side down on a pan, cover and rise 30 minutes. Heat oven to 375°F.","Bake 15 to 18 minutes until golden."]},
rancheros:{list:["8 eggs","8 corn tortillas","1 can (16 oz) refried beans","3/4 cup salsa","1/2 cup shredded cheese","3 tablespoons oil"],
 steps:["Warm the beans.","Fry the tortillas in 2 tablespoons oil 20 seconds per side until soft. Drain on a towel.","Fry the eggs in the rest of the oil.","Spread beans on 2 tortillas per plate, top with eggs, salsa and cheese."]},
cinnamonrolls:{list:["3 1/2 cups flour","1 packet (2 1/4 teaspoons) yeast","1 cup warm milk, plus 3 tablespoons for glaze","6 tablespoons butter, softened and divided","1 egg","1/4 cup sugar","1/2 teaspoon salt","3/4 cup brown sugar","1 tablespoon cinnamon","1 cup powdered sugar (or regular sugar blended fine)"],
 steps:["Stir the yeast and sugar into the warm milk and let sit 5 minutes. Mix in 2 tablespoons butter, the egg, salt and flour. Knead 5 minutes. Cover and rise 1 hour.","Roll into a 12x16 inch rectangle. Spread with 4 tablespoons butter and sprinkle with the brown sugar and cinnamon.","Roll up from the long side and cut into 12 rolls. Set in a greased 9x13 pan, cover and rise 30 minutes.","Heat oven to 350°F. Bake 22 to 25 minutes until golden.","Stir the powdered sugar with 3 tablespoons milk and drizzle over the warm rolls."]},
queso:{list:["1 block (8 oz) cheese, shredded","1 can (10 oz) tomatoes and green chiles, drained","1/2 can (6 oz) evaporated milk","1 teaspoon flour","1/2 bag (13 oz) tortilla chips"],
 steps:["Toss the shredded cheese with the flour.","Warm the evaporated milk in a small pot over medium low until steaming.","Add the cheese a handful at a time, stirring until smooth.","Stir in the tomatoes and green chiles and serve warm with chips."]},
elote:{list:["2 cans (15 oz each) corn, drained","2 tablespoons butter","3 tablespoons mayo","Juice of 1 lime","1/2 teaspoon chili powder","1/2 cup crumbled cheese (feta or parmesan)"],
 steps:["Melt the butter in a skillet over medium high. Cook the corn 6 to 8 minutes until some kernels char.","Take off the heat and stir in the mayo, lime juice and chili powder.","Spoon into cups and top with cheese."]},
tzatziki:{list:["2 cups plain yogurt","1/2 cucumber, grated and squeezed dry","Juice of 1/2 lemon","1/2 teaspoon garlic powder","1 tablespoon chopped herbs","1/4 teaspoon salt","6 pita breads","2 tablespoons oil"],
 steps:["Stir the yogurt, cucumber, lemon juice, garlic, herbs and salt. Chill while you make the chips.","Heat oven to 375°F. Cut each pita into 8 wedges and brush with oil.","Bake 10 minutes until crisp.","Serve the chips with the dip."]},
chips:{list:["12 corn tortillas","2 tablespoons oil for baking (or 2 cups for frying)","1/2 teaspoon salt"],
 steps:["Cut each tortilla into 6 wedges.","To bake: heat oven to 375°F, brush with oil and bake 12 minutes, turning once.","To fry: heat 1 inch of oil to 350°F and fry in batches 1 to 2 minutes until crisp.","Salt right away."]},
eggrolls:{list:["1 package (12 oz) egg roll or dumpling wrappers","1/2 lb ground pork (or 1 can chicken)","3 cups shredded cabbage","2 carrots, shredded","2 tablespoons soy sauce","1/2 teaspoon ground ginger","Oil for frying (about 2 cups) or 2 tablespoons for baking"],
 steps:["Brown the pork in a skillet. Add the cabbage, carrot, soy sauce and ginger and cook 5 minutes until soft. Cool 10 minutes.","Put 2 tablespoons filling near one corner of a wrapper. Fold the corner over, fold in the sides and roll up. Seal with water.","Fry in 350°F oil 3 to 4 minutes until golden, or brush with oil and bake at 425°F for 15 minutes, turning once."]},
roastedchickpeas:{list:["2 cans (15 oz each) chickpeas, drained and patted very dry","2 tablespoons oil","1 teaspoon chili powder or paprika","1/2 teaspoon garlic powder","1/2 teaspoon salt"],
 steps:["Heat oven to 400°F.","Toss the chickpeas with the oil and spread on a sheet pan.","Roast 30 minutes, shaking the pan once, until crunchy.","Toss with the seasonings while hot. Cool to get extra crunchy."]},
smoothie:{list:["2 cups frozen berries (or 2 bananas, or 1 can fruit)","1 cup yogurt","1 cup milk or juice"],
 steps:["Add the milk and yogurt to the blender first, then the fruit.","Blend until smooth, adding a splash more milk if too thick.","Pour into 4 cups."]},
garlicknots:{list:["1 lb pizza dough","3 tablespoons butter, melted","1/2 teaspoon garlic powder","2 tablespoons parmesan","1/2 teaspoon Italian seasoning"],
 steps:["Heat oven to 400°F and line a pan with parchment.","Cut the dough into 12 pieces and roll each into a 6 inch rope.","Tie each rope in a loose knot and set on the pan.","Bake 15 minutes until golden.","Stir the butter and garlic and brush over the hot knots. Sprinkle with parmesan and Italian seasoning."]},
applepie:{list:["2 pie crusts","6 apples, peeled and sliced","3/4 cup sugar (white or brown)","2 tablespoons flour","1 teaspoon cinnamon","2 tablespoons butter"],
 steps:["Heat oven to 400°F.","Toss the apples with the sugar, flour and cinnamon.","Fit one crust into a pie pan and fill with the apples. Dot with butter.","Top with the second crust, pinch the edges together and cut 4 slits in the top.","Bake 45 to 50 minutes until golden and bubbling. Cool 2 hours before slicing."]},
sweetpotpie:{list:["1 pie crust","2 cups mashed cooked sweet potato (about 2 medium, or 1 can drained)","1 can (12 oz) evaporated milk","2 eggs","2 tablespoons butter, melted","3/4 cup sugar","1 teaspoon cinnamon","1 teaspoon vanilla"],
 steps:["Heat oven to 350°F.","Beat the sweet potato with the butter until smooth.","Beat in the evaporated milk, eggs, sugar, cinnamon and vanilla.","Pour into the crust.","Bake 55 to 60 minutes until the center is set. Cool before slicing."]},
pumpkinpie:{list:["1 pie crust","1 can (15 oz) pumpkin","1 can (14 oz) sweetened condensed milk","2 eggs","1 1/2 teaspoons cinnamon","1/4 teaspoon salt"],
 steps:["Heat oven to 425°F.","Whisk the pumpkin, condensed milk, eggs, cinnamon and salt until smooth.","Pour into the crust.","Bake 15 minutes, then lower to 350°F and bake 35 to 40 minutes until a knife comes out clean.","Cool before slicing."]},
bananacreampie:{list:["1 pie crust, baked (or 1 1/2 cups crushed graham crackers with 5 tablespoons melted butter)","2 boxes (3.4 oz each) vanilla instant pudding","3 cups cold milk","3 bananas, sliced"],
 steps:["Bake the crust as the package says and cool, or press the graham crumbs and butter into a pie pan and chill.","Whisk the pudding mix and cold milk 2 minutes until thick.","Layer banana slices in the crust and cover with half the pudding.","Add the rest of the bananas and pudding.","Chill 3 hours before slicing."]},
nochurn:{list:["2 cups (1 pint) heavy cream, very cold","1 can (14 oz) sweetened condensed milk","2 teaspoons vanilla","1 cup mix ins, such as berries, mashed banana or 1/4 cup cocoa"],
 steps:["Beat the cold cream until stiff peaks form, about 3 minutes with a mixer.","Gently fold in the condensed milk, vanilla and mix ins.","Spread in a loaf pan or glass dish and cover.","Freeze at least 6 hours."]},
blackberrycobbler:{list:["4 cups frozen berries","1 cup flour","1 cup sugar","1 cup milk","2 teaspoons baking powder","1 stick (1/2 cup) butter"],
 steps:["Heat oven to 350°F. Put the butter in a 9x9 dish and set it in the oven until melted.","Whisk the flour, sugar, baking powder and milk.","Pour over the butter. Do not stir.","Scatter the berries on top.","Bake 45 minutes until golden."]},
tresleches:{list:["1 cup flour","1 1/2 teaspoons baking powder","5 eggs","1 cup sugar","1/3 cup milk","1 teaspoon vanilla","1 can (12 oz) evaporated milk","1 can (14 oz) sweetened condensed milk","1/2 cup heavy cream (or milk)"],
 steps:["Heat oven to 350°F and grease a 9x13 dish.","Beat the eggs and sugar 5 minutes until pale and thick. Beat in the 1/3 cup milk and vanilla.","Gently fold in the flour and baking powder.","Bake 25 minutes until golden. Cool 15 minutes.","Poke holes all over with a fork. Mix the evaporated milk, condensed milk and cream and pour slowly over the cake.","Chill overnight."]},
churros:{list:["1 cup water","2 tablespoons butter","1 tablespoon sugar, plus 1/2 cup for rolling","1/4 teaspoon salt","1 cup flour","1 egg","1 teaspoon cinnamon","Oil for frying (about 3 cups)"],
 steps:["Boil the water, butter, 1 tablespoon sugar and salt. Stir in the flour until a ball forms. Cool 5 minutes.","Beat in the egg until smooth.","Spoon into a zip bag and snip the corner.","Pipe 4 inch strips into 350°F oil and fry 2 minutes per side until golden.","Roll in 1/2 cup sugar mixed with the cinnamon."]},
chocpudding:{list:["3 cups milk","1/2 cup sugar","1/3 cup cocoa powder","3 tablespoons flour (or cornstarch)","1 teaspoon vanilla","Pinch of salt"],
 steps:["Whisk the sugar, cocoa, flour and salt in a pot, then slowly whisk in the milk.","Cook over medium, stirring constantly, 8 to 10 minutes until thick.","Stir in the vanilla.","Pour into cups, cover and chill 2 hours."]},
sugarcookies:{list:["2 1/4 cups flour","1 stick (1/2 cup) butter, softened","1 cup sugar","1 egg","1 teaspoon vanilla","1 teaspoon baking powder","1/4 teaspoon salt"],
 steps:["Heat oven to 350°F.","Beat the butter and sugar until fluffy, then beat in the egg and vanilla.","Stir in the flour, baking powder and salt.","Roll into 1 inch balls and set 2 inches apart on a pan.","Bake 9 to 10 minutes until the edges just set."]},
poundcake:{list:["2 cups flour","2 sticks (1 cup) butter, softened","1 1/2 cups sugar","4 eggs","1/4 cup milk","1 teaspoon vanilla","1/4 teaspoon salt"],
 steps:["Heat oven to 325°F and grease a loaf pan.","Beat the butter and sugar 3 minutes until fluffy.","Beat in the eggs one at a time.","Mix in the flour and salt, then the milk and vanilla.","Bake 60 to 70 minutes until a toothpick comes out clean."]},
roastturkey:{list:["1 whole turkey, about 12 lb, fully thawed","1 stick (1/2 cup) butter, softened","1 medium onion, quartered","2 celery stalks, cut in pieces","2 carrots, cut in pieces","1 tablespoon poultry seasoning","1 tablespoon salt","1 teaspoon pepper"],
 steps:["Heat oven to 325°F. Take out the neck and giblets and pat the turkey dry.","Mix the butter, salt, pepper and poultry seasoning. Rub under and over the skin.","Put the onion, celery and carrot inside the turkey.","Roast in a pan about 15 minutes per pound, about 3 hours, until the thickest part of the thigh reads 165°F.","Rest 30 minutes before carving. Save the pan drippings for gravy."]},
turkeygravy:{list:["Pan drippings from the turkey","Butter as needed to make 1/4 cup fat (up to 4 tablespoons)","1/4 cup flour","3 cups chicken broth","1/2 teaspoon poultry seasoning","Salt and pepper to taste"],
 steps:["Pour the drippings into a pot. Skim off the fat and add butter to make 1/4 cup fat.","Whisk in the flour over medium and cook 2 minutes.","Slowly whisk in the broth and the poultry seasoning.","Simmer 5 minutes until thick. Season with salt and pepper."]},
cranberryjelly:{list:["Canned: 1 can (14 oz) jellied cranberry sauce","Homemade: 1 bag (12 oz) fresh cranberries","Homemade: 1 cup sugar","Homemade: 1 cup water"],
 steps:["Canned: chill the can, open both ends and slide it out. Slice into rounds.","Homemade: bring the sugar and water to a boil, add the cranberries and simmer 10 minutes until they pop.","Cool, then chill at least 2 hours. It thickens as it cools."]},
greenbeancasserole:{list:["3 cans (14 oz each) green beans, drained","1 can (10 oz) cream of chicken or mushroom soup","1/2 cup milk","1 teaspoon soy sauce","1 can (6 oz) crispy fried onions, divided","1/4 teaspoon pepper"],
 steps:["Heat oven to 350°F.","Mix the green beans, soup, milk, soy sauce, pepper and half the onions in a baking dish.","Bake 25 minutes until bubbly.","Top with the rest of the onions and bake 5 minutes more."]}
});
Object.assign(FIX, {
holidaymac:{list:["1 lb elbow macaroni","2 blocks (8 oz each) sharp cheddar, shredded (about 4 cups), divided","1 can (12 oz) evaporated milk","1/2 cup milk","2 eggs","4 tablespoons butter, cut into small pieces","1 teaspoon salt","1/2 teaspoon pepper","1/2 teaspoon garlic powder (optional)"],
 steps:["Heat oven to 350°F and grease a 9x13 baking dish.","Boil the macaroni in salted water 2 minutes less than the box says. Drain well.","Whisk the eggs, evaporated milk, milk, salt, pepper and garlic powder in a bowl.","Spread half the macaroni in the dish. Dot with half the butter and sprinkle with 1 1/2 cups cheese.","Add the rest of the macaroni, the rest of the butter and another 1 1/2 cups cheese.","Pour the egg mixture evenly over the top and finish with the last cup of cheese.","Bake uncovered 40 to 45 minutes until set in the middle and golden on top. Rest 10 minutes so it slices into squares."],tip:"Shred a block yourself. It melts creamier and costs less than bagged cheese."}
});
